/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: Task.v
@@
     split; intros [Hv1 [Hv2 [U1 [body1 [U2 [body2 [E1 [E2 Hbody]]]]]]]];
-      repeat split; try assumption; exists U1, body1, U2, body2;
-      repeat split; try assumption; intros left_arg right_arg Harg.
+      split; [exact Hv1|]; split; [exact Hv2|];
+      exists U1, body1, U2, body2;
+      split; [exact E1|]; split; [exact E2|]; intros left_arg right_arg Harg.
@@
   - split; intros [Hv1 [Hv2 [body1 [body2 [E1 [E2 Hbody]]]]]];
-      repeat split; try assumption; exists body1, body2;
-      repeat split; try assumption; intros U1 U2 candidate HU1 HU2.
+      split; [exact Hv1|]; split; [exact Hv2|];
+      exists body1, body2;
+      split; [exact E1|]; split; [exact E2|];
+      intros U1 U2 inner_candidate HU1 HU2.
@@
-    + apply (lifting_equiv (value_relation (candidate :: eta)
+    + apply (lifting_equiv (value_relation (inner_candidate :: eta)
         (relation_update rho X candidate) T)
-        (value_relation (candidate :: eta) rho T));
+        (value_relation (inner_candidate :: eta) rho T));
@@
-    + apply (lifting_equiv (value_relation (candidate :: eta)
+    + apply (lifting_equiv (value_relation (inner_candidate :: eta)
         (relation_update rho X candidate) T)
-        (value_relation (candidate :: eta) rho T));
+        (value_relation (inner_candidate :: eta) rho T));
*** End Patch
PATCH
coqc Task.v 2>&1 | tail -26"

